INSERT OR IGNORE INTO task (key,src,org,poster,cat,by,title,title_th,what,what_th,place,href,site,price_kind,baht,price_note,unit,slots,state,created_at,shoup_at,ends_at) VALUES ('burmese-check','ours','hongdam','Hongdam','lang-check','human','Read Hongdam''s Burmese translation page and mark what reads wrong','อ่านหน้าแปลภาษาพม่าของหงส์ดำ แล้วบอกส่วนที่อ่านผิด','One page in Burmese (Unicode). Note each line that a Burmese reader would stop at.','หน้าภาษาพม่าหนึ่งหน้า (ยูนิโค้ด) จดบรรทัดที่คนพม่าอ่านแล้วสะดุด',NULL,'https://hongdam.net/translation/my/',NULL,'shoup',300,NULL,'a page',3,'open','2026-10-16T00:00:00.000Z','2026-10-16T00:00:00.000Z',NULL);
INSERT OR IGNORE INTO task (key,src,org,poster,cat,by,title,title_th,what,what_th,place,href,site,price_kind,baht,price_note,unit,slots,state,created_at,shoup_at,ends_at) VALUES ('shan-check','ours','cmvd','Chiang Mai Visa Desk','lang-shan','human','Read the Visa Desk''s Shan page for migrant workers','อ่านหน้าภาษาไทใหญ่สำหรับแรงงานของโต๊ะวีซ่า','A Shan reader marks each line that reads wrong on the migrant-workers page.','คนอ่านภาษาไทใหญ่ได้ จดบรรทัดที่อ่านผิดในหน้าแรงงานต่างด้าว',NULL,'https://chiangmaivisadesk.com/migrant-workers/',NULL,'shoup',500,NULL,'a page',3,'open','2026-10-16T00:00:00.000Z','2026-10-16T00:00:00.000Z',NULL);
INSERT OR IGNORE INTO task (key,src,org,poster,cat,by,title,title_th,what,what_th,place,href,site,price_kind,baht,price_note,unit,slots,state,created_at,shoup_at,ends_at) VALUES ('imp-lights','ours','motdang','Mot Dang','imp-lights','either','Traffic lights that read the road','ไฟจราจรที่อ่านถนนได้','Most of Chiang Mai''s traffic lights run on fixed timers, and queues back up around the moat and on the Superhighway at the same hours every day. Solved when one Chiang Mai junction runs light timing you built for 30 days and its measured wait is shorter than in the 30 days before.','ไฟจราจรส่วนใหญ่ในเชียงใหม่ตั้งเวลาตายตัว รถติดรอบคูเมืองและบนถนนซูเปอร์ไฮเวย์ช่วงเดิมทุกวัน สำเร็จเมื่อแยกหนึ่งในเชียงใหม่ใช้จังหวะไฟที่คุณทำครบ 30 วัน และเวลารอที่วัดได้สั้นกว่า 30 วันก่อนหน้า',NULL,NULL,NULL,'mirror',3000,'{"en": "Prayer, nam daeng, gratitude and $100", "th": "คำอธิษฐาน น้ำแดง ความขอบคุณ และ 100 ดอลลาร์"}',NULL,3,'open','2026-10-16T00:00:00.000Z','2026-10-16T00:00:00.000Z',NULL);
INSERT OR IGNORE INTO task (key,src,org,poster,cat,by,title,title_th,what,what_th,place,href,site,price_kind,baht,price_note,unit,slots,state,created_at,shoup_at,ends_at) VALUES ('imp-smoke','ours','motdang','Mot Dang','imp-smoke','human','A burning season without the burning','หน้าเผาที่ไม่ต้องเผา','From February to April, smoke from burnt fields and forest fires gives Chiang Mai some of the dirtiest air in the world. Part of it starts with farmers clearing land the cheapest way they have. Solved when 100 farms that burned last season clear their land another way for a whole season, at no more cost to the farmer, because of your work.','ตั้งแต่กุมภาพันธ์ถึงเมษายน ควันจากการเผาไร่และไฟป่าทำให้อากาศเชียงใหม่แย่ติดอันดับโลก ส่วนหนึ่งมาจากเกษตรกรที่เผาเพราะเป็นวิธีที่ถูกที่สุดที่มี สำเร็จเมื่อไร่ 100 แห่งที่เผาเมื่อฤดูที่แล้ว เปลี่ยนไปเตรียมดินด้วยวิธีอื่นครบหนึ่งฤดู โดยเกษตรกรไม่เสียเงินมากกว่าเดิม เพราะงานของคุณ',NULL,NULL,NULL,'mirror',3000,'{"en": "Prayer, nam daeng, gratitude and $100", "th": "คำอธิษฐาน น้ำแดง ความขอบคุณ และ 100 ดอลลาร์"}',NULL,3,'open','2026-10-16T00:00:00.000Z','2026-10-16T00:00:00.000Z',NULL);
INSERT OR IGNORE INTO task (key,src,org,poster,cat,by,title,title_th,what,what_th,place,href,site,price_kind,baht,price_note,unit,slots,state,created_at,shoup_at,ends_at) VALUES ('imp-trucks','ours','motdang','Mot Dang','imp-trucks','either','Every red truck on the map','รถแดงทุกคันบนแผนที่','Chiang Mai''s songthaew, the red shared pickup trucks (rot daeng), keep no timetable, and most keep no fixed route. Nobody can see where one is. Solved when anyone with a phone can see where the red trucks are and where each is headed, for 30 days running, with the drivers'' agreement.','สองแถวสีแดงของเชียงใหม่ (รถแดง) ไม่มีตารางเวลา และส่วนใหญ่ไม่มีเส้นทางตายตัว ไม่มีใครเห็นว่ารถอยู่ตรงไหน สำเร็จเมื่อใครก็ได้ที่มีโทรศัพท์เห็นว่ารถแดงอยู่ที่ไหนและกำลังไปทางไหน ต่อเนื่อง 30 วัน โดยคนขับยินยอม',NULL,NULL,NULL,'mirror',3000,'{"en": "Prayer, nam daeng, gratitude and $100", "th": "คำอธิษฐาน น้ำแดง ความขอบคุณ และ 100 ดอลลาร์"}',NULL,3,'open','2026-10-16T00:00:00.000Z','2026-10-16T00:00:00.000Z',NULL);
INSERT OR IGNORE INTO task (key,src,org,poster,cat,by,title,title_th,what,what_th,place,href,site,price_kind,baht,price_note,unit,slots,state,created_at,shoup_at,ends_at) VALUES ('imp-floods','ours','motdang','Mot Dang','imp-floods','either','Which streets flood, a day ahead','รู้ล่วงหน้าหนึ่งวันว่าถนนไหนจะท่วม','The Ping River flooded Chiang Mai in 2011 and again in 2024. People learn which streets will flood when the water reaches them. Solved when a forecast a day ahead, street by street, proves right through a whole rainy season, checked against where the water went.','แม่น้ำปิงท่วมเชียงใหม่ในปี 2554 และอีกครั้งในปี 2567 คนรู้ว่าถนนไหนท่วมก็ต่อเมื่อน้ำมาถึงแล้ว สำเร็จเมื่อการคาดการณ์ล่วงหน้าหนึ่งวันรายถนนแม่นตลอดหน้าฝน ตรวจกับที่ที่น้ำท่วมจริง',NULL,NULL,NULL,'mirror',3000,'{"en": "Prayer, nam daeng, gratitude and $100", "th": "คำอธิษฐาน น้ำแดง ความขอบคุณ และ 100 ดอลลาร์"}',NULL,3,'open','2026-10-16T00:00:00.000Z','2026-10-16T00:00:00.000Z',NULL);
INSERT OR IGNORE INTO task (key,src,org,poster,cat,by,title,title_th,what,what_th,place,href,site,price_kind,baht,price_note,unit,slots,state,created_at,shoup_at,ends_at) VALUES ('imp-leaves','ours','motdang','Mot Dang','imp-leaves','either','Read every Lanna palm-leaf manuscript','อ่านคัมภีร์ใบลานล้านนาทุกผูก','Temples across the north keep palm-leaf manuscripts in Lanna script (tua mueang): law, medicine, history, the Buddha''s teaching. Few people alive can read them. Solved when a machine reads Lanna script from photos of palm leaves as well as a trained reader, checked by one on 100 leaves it has not seen.','วัดทั่วภาคเหนือเก็บคัมภีร์ใบลานอักษรธรรมล้านนา (ตัวเมือง) ทั้งกฎหมาย ตำรายา ประวัติศาสตร์ และพระธรรม คนที่อ่านได้เหลือน้อย สำเร็จเมื่อเครื่องอ่านอักษรล้านนาจากภาพใบลานได้เท่าคนที่อ่านเป็น ตรวจโดยคนอ่านเป็นกับใบลาน 100 ใบที่เครื่องไม่เคยเห็น',NULL,NULL,NULL,'mirror',3000,'{"en": "Prayer, nam daeng, gratitude and $100", "th": "คำอธิษฐาน น้ำแดง ความขอบคุณ และ 100 ดอลลาร์"}',NULL,3,'open','2026-10-16T00:00:00.000Z','2026-10-16T00:00:00.000Z',NULL);
INSERT OR IGNORE INTO task (key,src,org,poster,cat,by,title,title_th,what,what_th,place,href,site,price_kind,baht,price_note,unit,slots,state,created_at,shoup_at,ends_at) VALUES ('imp-address','ours','motdang','Mot Dang','imp-address','either','An address a stranger can find','ที่อยู่ที่คนแปลกหน้าหาเจอ','House numbers in Chiang Mai often run in the order houses were registered, not along the street, and many sois have no name sign. Drivers phone ahead. Solved when every door in one Chiang Mai tambon (subdistrict) has an address that a stranger finds on the first try, tested at 100 doors picked at random.','บ้านเลขที่ในเชียงใหม่มักเรียงตามลำดับที่จดทะเบียน ไม่ได้เรียงตามถนน หลายซอยไม่มีป้ายชื่อ คนส่งของต้องโทรถาม สำเร็จเมื่อทุกประตูในตำบลหนึ่งของเชียงใหม่มีที่อยู่ที่คนแปลกหน้าหาเจอในครั้งแรก ทดสอบที่ 100 ประตูที่สุ่มเลือก',NULL,NULL,NULL,'mirror',3000,'{"en": "Prayer, nam daeng, gratitude and $100", "th": "คำอธิษฐาน น้ำแดง ความขอบคุณ และ 100 ดอลลาร์"}',NULL,3,'open','2026-10-16T00:00:00.000Z','2026-10-16T00:00:00.000Z',NULL);
INSERT OR IGNORE INTO task (key,src,org,poster,cat,by,title,title_th,what,what_th,place,href,site,price_kind,baht,price_note,unit,slots,state,created_at,shoup_at,ends_at) VALUES ('imp-open','ours','motdang','Mot Dang','imp-open','either','Know what is open right now','รู้ว่าร้านไหนเปิดอยู่ตอนนี้','Opening hours on maps and listings are wrong often enough that people in Chiang Mai phone first, or ride over and find the shutter down. Solved when Mot Dang says open or closed correctly 99 times in 100 for 1,000 Chiang Mai businesses, checked at the door at random hours over a month.','เวลาเปิดปิดบนแผนที่และเว็บต่างๆ ผิดบ่อยจนคนเชียงใหม่ต้องโทรถามก่อน หรือขี่ไปแล้วเจอร้านปิด สำเร็จเมื่อมดแดงบอกว่าเปิดหรือปิดถูก 99 ครั้งใน 100 สำหรับร้าน 1,000 ร้านในเชียงใหม่ ตรวจที่หน้าร้านในเวลาสุ่มตลอดหนึ่งเดือน',NULL,NULL,NULL,'mirror',3000,'{"en": "Prayer, nam daeng, gratitude and $100", "th": "คำอธิษฐาน น้ำแดง ความขอบคุณ และ 100 ดอลลาร์"}',NULL,3,'open','2026-10-16T00:00:00.000Z','2026-10-16T00:00:00.000Z',NULL);
INSERT OR IGNORE INTO task (key,src,org,poster,cat,by,title,title_th,what,what_th,place,href,site,price_kind,baht,price_note,unit,slots,state,created_at,shoup_at,ends_at) VALUES ('imp-roads','ours','motdang','Mot Dang','imp-roads','human','Half the deaths on the road','คนตายบนถนนลดลงครึ่งหนึ่ง','Thailand''s roads are among the deadliest in the world, and most who die on them are on motorbikes. Solved when road deaths in Chiang Mai province fall by half against the average of the five years before, and stay there for a year, because of your work.','ถนนเมืองไทยอันตรายติดอันดับโลก และคนที่ตายบนถนนส่วนใหญ่ขี่มอเตอร์ไซค์ สำเร็จเมื่อจำนวนคนตายบนถนนในจังหวัดเชียงใหม่ลดลงครึ่งหนึ่งเทียบกับค่าเฉลี่ยห้าปีก่อนหน้า และคงอยู่อย่างนั้นหนึ่งปี เพราะงานของคุณ',NULL,NULL,NULL,'mirror',3000,'{"en": "Prayer, nam daeng, gratitude and $100", "th": "คำอธิษฐาน น้ำแดง ความขอบคุณ และ 100 ดอลลาร์"}',NULL,3,'open','2026-10-16T00:00:00.000Z','2026-10-16T00:00:00.000Z',NULL);
INSERT OR IGNORE INTO task (key,src,org,poster,cat,by,title,title_th,what,what_th,place,href,site,price_kind,baht,price_note,unit,slots,state,created_at,shoup_at,ends_at) VALUES ('imp-dogs','ours','motdang','Mot Dang','imp-dogs','human','Someone for every soi dog','หมาซอยทุกตัวมีคนดูแล','Street dogs live on most sois in Chiang Mai. Some are fed and loved, some bite, and every year more are born. Solved when every street dog in one Chiang Mai tambon is vaccinated against rabies, sterilised, fed, and has a named person who answers for it, for a year.','หมาจรอยู่แทบทุกซอยในเชียงใหม่ บางตัวมีคนให้ข้าวและรัก บางตัวกัด และทุกปีมีลูกหมาเกิดใหม่ สำเร็จเมื่อหมาจรทุกตัวในตำบลหนึ่งของเชียงใหม่ได้ฉีดวัคซีนพิษสุนัขบ้า ทำหมัน มีข้าวกิน และมีคนที่ระบุชื่อดูแลรับผิดชอบ ครบหนึ่งปี',NULL,NULL,NULL,'mirror',3000,'{"en": "Prayer, nam daeng, gratitude and $100", "th": "คำอธิษฐาน น้ำแดง ความขอบคุณ และ 100 ดอลลาร์"}',NULL,3,'open','2026-10-16T00:00:00.000Z','2026-10-16T00:00:00.000Z',NULL);
INSERT OR IGNORE INTO task (key,src,org,poster,cat,by,title,title_th,what,what_th,place,href,site,price_kind,baht,price_note,unit,slots,state,created_at,shoup_at,ends_at) VALUES ('imp-tap','ours','motdang','Mot Dang','imp-tap','human','Water you drink from the tap','น้ำประปาที่ดื่มได้จากก๊อก','Chiang Mai buys its drinking water in bottles and from coin machines on the street, because few people trust the tap. Solved when the water at every tap in one Chiang Mai neighbourhood passes Thailand''s drinking-water standard each month for a year, and the people who live there drink it.','คนเชียงใหม่ซื้อน้ำดื่มเป็นขวด และจากตู้หยอดเหรียญริมถนน เพราะไม่ค่อยมีใครเชื่อน้ำก๊อก สำเร็จเมื่อน้ำจากทุกก๊อกในชุมชนหนึ่งของเชียงใหม่ผ่านมาตรฐานน้ำดื่มของไทยทุกเดือนครบหนึ่งปี และคนที่อยู่ที่นั่นดื่มน้ำนั้น',NULL,NULL,NULL,'mirror',3000,'{"en": "Prayer, nam daeng, gratitude and $100", "th": "คำอธิษฐาน น้ำแดง ความขอบคุณ และ 100 ดอลลาร์"}',NULL,3,'open','2026-10-16T00:00:00.000Z','2026-10-16T00:00:00.000Z',NULL);
INSERT OR IGNORE INTO task (key,src,org,poster,cat,by,title,title_th,what,what_th,place,href,site,price_kind,baht,price_note,unit,slots,state,created_at,shoup_at,ends_at) VALUES ('imp-ping','ours','motdang','Mot Dang','imp-ping','human','A Ping River you can swim in','แม่น้ำปิงที่ลงว่ายได้','The Ping carries the city''s drains and the farms'' run-off through the middle of Chiang Mai. Solved when the river at Nawarat Bridge meets Thailand''s surface-water standard for swimming (class 2) every month for a year.','แม่น้ำปิงพาน้ำทิ้งจากท่อในเมืองและน้ำจากไร่นาไหลผ่านกลางเชียงใหม่ สำเร็จเมื่อน้ำที่สะพานนวรัฐผ่านมาตรฐานคุณภาพน้ำผิวดินประเภทที่ 2 (ว่ายน้ำได้) ทุกเดือนครบหนึ่งปี',NULL,NULL,NULL,'mirror',3000,'{"en": "Prayer, nam daeng, gratitude and $100", "th": "คำอธิษฐาน น้ำแดง ความขอบคุณ และ 100 ดอลลาร์"}',NULL,3,'open','2026-10-16T00:00:00.000Z','2026-10-16T00:00:00.000Z',NULL);
INSERT OR IGNORE INTO task (key,src,org,poster,cat,by,title,title_th,what,what_th,place,href,site,price_kind,baht,price_note,unit,slots,state,created_at,shoup_at,ends_at) VALUES ('imp-coffee','ours','motdang','Mot Dang','imp-coffee','human','The farmer''s share of a cup','ส่วนของเกษตรกรในกาแฟหนึ่งแก้ว','Coffee grows in the hills around Chiang Mai on Lahu, Akha and Karen farms, and a cup of it in town costs more than a farmer is paid for a kilo of coffee cherries. Solved when 100 hill farms earn as much from each cup of their coffee as the café that pours it, for a year.','กาแฟปลูกบนดอยรอบเชียงใหม่ ในไร่ของชาวลาหู่ อาข่า และกะเหรี่ยง กาแฟหนึ่งแก้วในเมืองแพงกว่าที่เกษตรกรได้จากเชอร์รีกาแฟหนึ่งกิโล สำเร็จเมื่อไร่บนดอย 100 แห่งได้เงินจากกาแฟของตัวเองแต่ละแก้วเท่ากับร้านที่ชงขาย ครบหนึ่งปี',NULL,NULL,NULL,'mirror',3000,'{"en": "Prayer, nam daeng, gratitude and $100", "th": "คำอธิษฐาน น้ำแดง ความขอบคุณ และ 100 ดอลลาร์"}',NULL,3,'open','2026-10-16T00:00:00.000Z','2026-10-16T00:00:00.000Z',NULL);
