INSERT OR IGNORE INTO task (key,src,org,poster,cat,by,title,title_th,what,what_th,place,href,site,price_kind,baht,price_note,unit,slots,state,created_at,shoup_at,ends_at) VALUES ('fb-deebd8a2f5e8','elsewhere',NULL,'Chiang Mai Media and Creative','jobs-media','human','Creative Producer, full-time · Chiang Mai Media and Creative','Creative Producer / ผู้ดูแลการผลิตคอนเทนต์ พนักงานประจำ','Plan and make photo and video content about Chiang Mai news, travel and restaurant reviews, with the photo, editing, graphics and admin teams. Run interviews, write captions, plan the posting schedule, work with clients, plan and run shoots.
Age 23–35; writes and communicates well; calm under pressure; manages time. Content, production, photo or editing experience counts in your favour.
Office in Mueang Chiang Mai. Send a CV and portfolio.
Apply: LINE @995tuuld · 098-814-7028','คิดและสร้างสรรค์คอนเทนต์ทั้งภาพนิ่งและวิดีโอ เนื้อหาเกี่ยวกับข่าวสารต่าง ๆ ในจังหวัดเชียงใหม่ รีวิวท่องเที่ยว ร้านอาหาร ร่วมกับทีมช่างภาพ ทีมตัดต่อ ทีมกราฟิก และแอดมิน ดูแลรายการสัมภาษณ์ เขียนแคปชัน วางแผนการลงคอนเทนต์ ประสานงานกับลูกค้า วางแผนและดูแลการถ่ายทำ
อายุ 23–35 ปี เขียนและสื่อสารได้ดี ใจเย็น แก้ปัญหาเฉพาะหน้าได้ รับผิดชอบ บริหารเวลาได้ดี มีประสบการณ์ด้านคอนเทนต์ โปรดักชัน ถ่ายภาพ หรือตัดต่อจะพิจารณาเป็นพิเศษ
ออฟฟิศอยู่ อ.เมือง จ.เชียงใหม่ ส่งประวัติและผลงาน
